//! Real generated guards and native SQLite; this fixture is generated by the app-owned tool.
pub mod generated;
use generated::contracts::{
    profile::{CreateProfile, Profile},
    public::{PatchProfile, ProfileKey},
};
use generated::stores::{
    profile::{ProfileStore, Profiles},
    schema,
};
use serde_json::{Value, json};
use stackpress_framework_schema::{SchemaResult, ValueContext, ValueProviders};
use stackpress_framework_sql::{DataErrorKind, DataSession};
use stackpress_sql::{DialectId, Engine, Insert, Row, Select, SqlValue};
use stackpress_sql_sqlite::{SqliteDatabase, SqliteOptions};

/// An explicit host checks redacted rules against its own declaration; no private bound is public.
struct Values {
    token: &'static str,
    secret: &'static str,
}
impl ValueProviders for Values {
    fn generate(&self, name: &str, _args: &[Value]) -> SchemaResult<Value> {
        Ok(json!(if name == "nanoid" {
            self.token
        } else {
            assert_eq!(name, "default:Profile.secret");
            self.secret
        }))
    }
    fn validate(&self, name: &str, value: &Value, _args: &[Value]) -> SchemaResult<bool> {
        let maximum = if name.starts_with("private:Profile.token.") {
            7
        } else {
            assert!(name.starts_with("private:Profile.secret."));
            5
        };
        Ok(value
            .as_str()
            .is_some_and(|value| value.chars().count() <= maximum))
    }
}
/// Deliberately permissive host policy proves the native storage guard is independent.
struct Permissive;
impl ValueProviders for Permissive {
    fn generate(&self, _: &str, _: &[Value]) -> SchemaResult<Value> {
        Ok(json!("ok"))
    }
    fn validate(&self, _: &str, _: &Value, _: &[Value]) -> SchemaResult<bool> {
        Ok(true)
    }
}
fn input(value: Value) -> CreateProfile {
    serde_json::from_value(value).unwrap()
}
fn row(value: &Profile) -> Row {
    Row::new(
        ProfileStore::encode(value)
            .unwrap()
            .into_iter()
            .zip(ProfileStore::table().unwrap().fields)
            .map(|(value, field)| (field.name, value))
            .collect(),
    )
}

#[tokio::main(flavor = "current_thread")]
async fn main() {
    let values = Values {
        token: "😀😀",
        secret: "e\u{301}",
    };
    let context = ValueContext {
        now: None,
        providers: Some(&values),
    };
    assert_eq!(stackpress_framework_schema::CONTRACT_REVISION, 3);
    let definitions = schema::definition().unwrap();
    for table in &definitions {
        assert!(table.create().render(DialectId::Mysql).is_err());
        assert!(
            table
                .create()
                .render(DialectId::Postgres)
                .unwrap()
                .queries()[0]
                .sql()
                .contains("VARCHAR(2)")
        );
    }
    let mysql = schema::mysql_definition("utf8mb4_bin", 16384).unwrap();
    assert!(mysql.iter().all(|table| {
        table.create().render(DialectId::Mysql).unwrap().queries()[0]
            .sql()
            .contains("ROW_FORMAT=DYNAMIC")
    }));
    let mut snapshots = std::collections::BTreeMap::new();
    for (dialect, name) in [
        (DialectId::Sqlite, "sqlite"),
        (DialectId::Postgres, "postgres"),
        (DialectId::Mysql, "mysql"),
    ] {
        let tables = if dialect == DialectId::Mysql {
            &mysql
        } else {
            &definitions
        };
        snapshots.insert(
            name,
            tables
                .iter()
                .flat_map(|table| {
                    table
                        .create()
                        .render(dialect)
                        .unwrap()
                        .queries()
                        .iter()
                        .map(|q| q.sql().to_owned())
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>(),
        );
    }
    std::fs::write(
        std::env::var("G37_SNAPSHOTS").unwrap(),
        serde_json::to_string_pretty(&snapshots).unwrap(),
    )
    .unwrap();
    for good in ["ab", "😀😀", "e\u{301}", "a\0", "a "] {
        let value = input(json!({"id":"p1","name":good}))
            .prepare_with(&context)
            .unwrap();
        assert_eq!(ProfileStore::decode(row(&value)).unwrap(), value);
    }
    for bad in ["abc", "😀😀😀", "e\u{301}x", "a\0x", "a  "] {
        assert!(
            input(json!({"id":"p1","name":bad}))
                .prepare_with(&context)
                .is_err()
        );
    }
    for (token, secret) in [("12345678", "ok"), ("ok", "123456")] {
        let values = Values { token, secret };
        let context = ValueContext {
            now: None,
            providers: Some(&values),
        };
        assert!(input(json!({"id":"p1"})).prepare_with(&context).is_err());
    }
    let prepared = input(json!({"id":"p1"})).prepare_with(&context).unwrap();
    for (secret, token) in [
        (Some("123456".into()), "ok".into()),
        (None, "12345678".into()),
    ] {
        let invalid = Profile {
            secret,
            token,
            ..prepared.clone()
        };
        assert!(ProfileStore::encode(&invalid).is_err());
        // Bypass encoding deliberately to represent externally written invalid private data.
        let mut cells = row(&prepared).cells().to_vec();
        for (name, value) in &mut cells {
            if name == "secret" {
                *value = invalid
                    .secret
                    .clone()
                    .map(SqlValue::Text)
                    .unwrap_or(SqlValue::Null);
            }
            if name == "token" {
                *value = invalid.token.clone().into();
            }
        }
        assert_eq!(
            ProfileStore::decode(Row::new(cells)).unwrap_err().kind(),
            DataErrorKind::Decode
        );
    }
    let root = tempfile::tempdir_in("/private/tmp").unwrap();
    let engine = Engine::new(
        SqliteDatabase::open(
            SqliteOptions::file(root.path().join("generated.sqlite")).create_if_missing(true),
        )
        .await
        .unwrap(),
    );
    for table in &definitions {
        engine
            .execute_plan(&table.create().render(DialectId::Sqlite).unwrap())
            .await
            .unwrap();
    }
    let mut db = DataSession::pooled(&engine);
    Profiles::create_with(&mut db, input(json!({"id":"p1"})), &context)
        .await
        .unwrap();
    // Exercise actual generated RETURNING round trips for every character-count edge.
    for name in ["", "😀😀", "e\u{301}", "a\0", "a "] {
        let created =
            Profiles::create_with(&mut db, input(json!({"id":"k1","name":name})), &context)
                .await
                .unwrap();
        assert_eq!(created.name, name);
        assert!(
            Profiles::delete(&mut db, &ProfileKey { id: "k1".into() })
                .await
                .unwrap()
                .is_some()
        );
    }
    generated::stores::project::Projects::create_with(
        &mut db,
        serde_json::from_value(json!({"id":"r1","ownerId":"p1","title":"ok"})).unwrap(),
        &context,
    )
    .await
    .unwrap();
    generated::stores::task::Tasks::create_with(
        &mut db,
        serde_json::from_value(json!({"id":"t1","projectId":"r1","title":"ok"})).unwrap(),
        &context,
    )
    .await
    .unwrap();
    let page = Profiles::search_atomic(
        &engine,
        generated::stores::profile::Query {
            q: Some("ok".into()),
            total: true,
            take: 1,
            includes: vec!["projects.tasks".into()],
            ..Default::default()
        },
    )
    .await
    .unwrap();
    assert_eq!(page.total, Some(1));
    let stackpress_framework_sql::stores::Loaded::Loaded(projects) = &page.rows[0].projects else {
        panic!("projects not loaded")
    };
    let stackpress_framework_sql::stores::Loaded::Loaded(tasks) = &projects[0].tasks else {
        panic!("tasks not loaded")
    };
    assert_eq!(tasks[0].row.title, "ok");
    assert_eq!(
        Profiles::get(&mut db, "p1").await.unwrap().unwrap(),
        prepared
    );
    let mut transaction = engine.begin().await.unwrap();
    assert!(
        generated::stores::project::Projects::detail(
            &mut DataSession::transaction(&mut transaction),
            &generated::contracts::public::ProjectKey { id: "r1".into() }
        )
        .await
        .unwrap()
        .is_some()
    );
    transaction.rollback().await.unwrap();
    let permissive = Permissive;
    let permissive_context = ValueContext {
        now: None,
        providers: Some(&permissive),
    };
    let prepared_bad = input(json!({"id":"p2","secret":"123456"}))
        .prepare_with(&permissive_context)
        .unwrap();
    assert!(ProfileStore::insert(&prepared_bad).is_err());
    let patch: PatchProfile = serde_json::from_value(json!({"secret":"123456"})).unwrap();
    let key = ProfileKey { id: "p1".into() };
    assert!(ProfileStore::update_plan(&key, &patch, &permissive_context).is_err());
    let mut transaction = engine.begin().await.unwrap();
    let items = vec![
        generated::stores::profile::BatchInput::Create {
            input: input(json!({"id":"p2"})),
        },
        generated::stores::profile::BatchInput::Create {
            input: input(json!({"id":"p3","name":"a  "})),
        },
    ];
    assert!(
        Profiles::batch(
            &mut DataSession::transaction(&mut transaction),
            items,
            &context
        )
        .await
        .is_err()
    );
    transaction.rollback().await.unwrap();
    assert_eq!(
        engine
            .fetch(&Select::new(["id"]).from("profile"))
            .await
            .unwrap()
            .len(),
        1
    );
    // A direct SQL writer can bypass SQLite's declared width; generated decoding refuses it.
    engine
        .execute(
            &Insert::new("profile")
                .columns(["id", "name", "secret", "token"])
                .values(["p2", "a  ", "ok", "ok"]),
        )
        .await
        .unwrap();
    let external = engine
        .fetch(&Select::default().from("profile").where_eq("id", "p2"))
        .await
        .unwrap()
        .remove(0);
    assert_eq!(
        ProfileStore::decode(external).unwrap_err().kind(),
        DataErrorKind::Decode
    );
    engine.close().await.unwrap();
    println!("G38 generated guards and SQLite proof passed; network DDL rendered only");
}
